DO $migration$
DECLARE
  v_table text;
  v_source_count integer;
  v_target_count integer;
  v_source_tables constant text[] := ARRAY[
    'sample',
    'sample_box',
    'sample_event',
    'sample_shipment_item',
    'sample_attachment',
    'sample_comments',
    'sample_factory_group'
  ];
BEGIN
  IF to_regnamespace('plm') IS NULL OR to_regnamespace('dflow') IS NULL THEN
    RAISE EXCEPTION 'Issue #26 requires both plm and dflow schemas';
  END IF;

  SELECT count(*) INTO v_source_count
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'plm'
    AND c.relname = ANY (v_source_tables)
    AND c.relkind = 'r';

  SELECT count(*) INTO v_target_count
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'dflow'
    AND c.relname = ANY (v_source_tables);

  IF v_source_count = 0 AND v_target_count = 7 THEN
    -- Safe idempotent replay after all objects have already moved.
    RETURN;
  END IF;

  IF v_source_count <> 7 OR v_target_count <> 0 THEN
    RAISE EXCEPTION
      'Issue #26 refuses a partial or conflicting state: plm sources=%, dflow targets=%',
      v_source_count, v_target_count;
  END IF;

  FOREACH v_table IN ARRAY v_source_tables LOOP
    EXECUTE format(
      'INSERT INTO issue_26_object_evidence (table_name, relation_oid, relation_file, row_count)
       SELECT %L, c.oid, c.relfilenode, (SELECT count(*) FROM %I.%I)
       FROM pg_class c
       JOIN pg_namespace n ON n.oid = c.relnamespace
       WHERE n.nspname = %L AND c.relname = %L AND c.relkind = %L
       ',
      v_table, 'plm', v_table, 'plm', v_table, 'r'
    );
  END LOOP;

  FOREACH v_table IN ARRAY v_source_tables LOOP
    EXECUTE format('ALTER TABLE %I.%I SET SCHEMA %I', 'plm', v_table, 'dflow');
  END LOOP;
END
