DO $verification$
DECLARE
  v_table text;
  v_expected record;
  v_actual_oid oid;
  v_actual_file oid;
  v_actual_rows bigint;
  v_source_tables constant text[] := ARRAY[
    'sample',
    'sample_box',
    'sample_event',
    'sample_shipment_item',
    'sample_attachment',
    'sample_comments',
    'sample_factory_group'
  ];
BEGIN
  FOREACH v_table IN ARRAY v_source_tables LOOP
    IF to_regclass(format('plm.%I', v_table)) IS NOT NULL THEN
      RAISE EXCEPTION 'Issue #26 left source relation plm.% behind', v_table;
    END IF;

    SELECT c.oid, c.relfilenode INTO v_actual_oid, v_actual_file
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'dflow' AND c.relname = v_table AND c.relkind = 'r';

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Issue #26 did not create ordinary table dflow.%', v_table;
    END IF;

    SELECT * INTO v_expected
    FROM issue_26_object_evidence e
    WHERE e.table_name = v_table;

    -- No evidence row means this is an idempotent replay after a completed move.
    IF FOUND THEN
      EXECUTE format('SELECT count(*) FROM %I.%I', 'dflow', v_table)
        INTO v_actual_rows;

      IF v_actual_oid <> v_expected.relation_oid
         OR v_actual_file <> v_expected.relation_file
         OR v_actual_rows <> v_expected.row_count THEN
        RAISE EXCEPTION
          'Issue #26 object identity or row-count mismatch for dflow.%', v_table;
      END IF;
    END IF;
  END LOOP;

  IF (
    SELECT count(*)
    FROM pg_class s
    JOIN pg_depend d ON d.objid = s.oid AND d.deptype IN ('a', 'i')
    JOIN pg_class t ON t.oid = d.refobjid
    JOIN pg_namespace tn ON tn.oid = t.relnamespace
    JOIN pg_namespace sn ON sn.oid = s.relnamespace
    WHERE s.relkind = 'S'
      AND tn.nspname = 'dflow'
      AND sn.nspname = 'dflow'
      AND t.relname = ANY (v_source_tables)
  ) <> 7 THEN
    RAISE EXCEPTION 'Issue #26 expected all seven owned identity sequences in dflow';
  END IF;
END
